&\Big|\Phi_+\Big(1-\frac{\eta^2}{2}+i\gamma\eta
  \Big)\Big|<1-\frac{1}{2}(\gamma|\eta|)^{1/2},\quad \eta^2\leqslant \delta.
\end{align*}

\begin{align*}
&\Big|\Phi_+\Big(1-\frac{\eta^2}{2}+i\gamma\eta
  \Big)\Big|\leqslant 1-\frac{1}{2}\Big(\frac{2^{1/2}\gamma}{\pi n}\Big)^{1/2},\qquad |\eta|<\delta
\end{align*}

\begin{align*}
&\limsup_{n\to+\infty}\sup_{\eta\in A_n,|\eta|<\delta}\Big|\Phi_+\left(1-\frac{\eta^2}{2}+i\gamma\eta
  \right)\Big|^{n+1}\leqslant \limsup_{n\to+\infty}\bigg[1-\frac{1}{2}\Big(\frac{2^{1/2}\gamma}{\pi
  n}\Big)^{1/2}\bigg]^{n+1}=0.
\end{align*}

$$
|c_n(\eta)|\lesssim \underset{{k\in \widehat{{\mathbb I}}_n}}{{\widehat\sum}}\frac{1}{4\sin^2(\pi k)+|\eta|
}\lesssim \int_0^1\frac{dk}{k^2+|\eta|}\lesssim \frac{1}{|\eta|^{1/2}}
$$
